import React, { useState } from 'react';
import Hero from './Hero';
import PrimaryButton from './PrimaryButton';

const Home = () => {
    // State для показу додаткового контенту
    const [showMore, setShowMore] = useState(false);

    return (
        <>
            <Hero />
            
            <section className="container" style={{ padding: '50px 20px', textAlign: 'center' }}>
                <h2>Welcome to FilmFest</h2>
                <p style={{ maxWidth: '600px', margin: '0 auto 30px', color: '#b3b3b3' }}>
                    We bring you the best cinematic experiences from around the world.
                </p>

                <PrimaryButton onClick={() => setShowMore(!showMore)}>
                    {showMore ? 'Hide Details' : 'View More Info'}
                </PrimaryButton>

                {/* Умовний рендеринг (Conditional Rendering) */}
                {showMore && (
                    <div style={{ marginTop: '30px', padding: '20px', background: '#2e2e2e', borderRadius: '8px' }}>
                        <h3>About Our Festival</h3>
                        <p>FilmFest was founded in 2024 to celebrate the art of storytelling.</p>
                        <p>We feature independent films, massive blockbusters, and exclusive concerts.</p>
                        <p style={{ color: '#e50914' }}>Join us for the next season!</p>
                    </div>
                )}
            </section>
        </>
    );
};

export default Home;
